'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function initIntroSplash(){const splash=$('#intro-splash');if(!splash)return;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const started=performance.now();let finished=false;const close=()=>{if(finished)return;finished=true;const wait=Math.max(0,(reduced?900:2350)-(performance.now()-started));window.setTimeout(()=>{document.body.classList.add('site-ready');if(reduced){splash.remove();return}splash.classList.add('is-leaving');window.setTimeout(()=>splash.remove(),950)},wait)};window.addEventListener('load',close,{once:true});window.setTimeout(close,3500)}
initIntroSplash();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const imageURL=s=>typeof s==='string'&&(/^(assets\/|data:image\/(png|jpeg|webp);base64,)/.test(s)||/^https:\/\//.test(s))?s:'';
const safeURL=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:''}catch{return ''}};
let data, baseData, currentTab='president', currentCity='ankara';
const dialog=$('#dialog');let lastFocus;
function openDialog(content){dialog.classList.remove('admin-panel');lastFocus=document.activeElement;$('#dialog-content').innerHTML=content;if(!dialog.open)dialog.showModal();$('.dialog-close').focus()}
$('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.classList.remove('admin-panel');lastFocus?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
$('.menu-toggle').onclick=()=>{const open=$('nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open)};
document.querySelectorAll('.site-header nav a, .site-header nav button').forEach(a=>a.addEventListener('click',()=>{
 if(a.classList.contains('dropdown-trigger'))return;
 document.querySelector('.site-header nav').classList.remove('open');
 document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');
 closeHeaderDropdowns();
}));
function closeHeaderDropdowns(){document.querySelectorAll('.site-header .dropdown').forEach(d=>setHeaderDropdown(d,false))}
function setHeaderDropdown(d,open){d.classList.toggle('is-open',open);d.querySelector('.dropdown-trigger').setAttribute('aria-expanded',String(open));d.querySelector('.submenu').inert=!open}
document.querySelectorAll('.site-header .dropdown').forEach(d=>{
 const trigger=d.querySelector('.dropdown-trigger');let leaveTimer;
 d.addEventListener('mouseenter',()=>{if(matchMedia('(hover:hover) and (min-width:981px)').matches){clearTimeout(leaveTimer);setHeaderDropdown(d,true)}});
 d.addEventListener('mouseleave',()=>{leaveTimer=setTimeout(()=>{if(!d.contains(document.activeElement))setHeaderDropdown(d,false)},130)});
 trigger.addEventListener('click',()=>{clearTimeout(leaveTimer);setHeaderDropdown(d,!d.classList.contains('is-open'))});
 trigger.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();setHeaderDropdown(d,true);d.querySelector('.submenu a').focus()}});
 d.addEventListener('focusout',()=>{setTimeout(()=>{if(!d.contains(document.activeElement))setHeaderDropdown(d,false)},0)});
 d.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();setHeaderDropdown(d,false);trigger.focus()}});
});
document.addEventListener('click',e=>{if(!e.target.closest('.site-header .dropdown'))closeHeaderDropdowns()});

const slides=[{title:'Şuurlu Gençlik<br><em>Güçlü Türkiye</em>',desc:'Ahlak, ilim ve sorumlulukla yarınları birlikte inşa ediyoruz.',caption:'ÖNCE AHLAK VE MANEVİYAT'},{title:'Birlikte Öğrenir,<br><em>Birlikte Üretiriz</em>',desc:'Öğreniyor, üretiyor; gençliğin emeğini geleceğe taşıyoruz.',caption:'İMAN · ŞUUR · EMEK'},{title:'Köklerden Güç,<br><em>Geleceğe Umut</em>',desc:'Köklerimizden güç alıp ilim ve kardeşlikle yürüyoruz.',caption:'AYNI İDEAL, AYNI HEYECAN'},{title:'Ahlaklı Gençlik,<br><em>Güçlü Türkiye</em>',desc:'Şuurlu ve sorumluluk sahibi gençlerle geleceğe yürüyoruz.',caption:'GELECEĞE BİRLİKTE'}];
let slide=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,timer;
$('#dots').innerHTML=slides.map((_,i)=>`<button aria-label="${i+1}. slayt" data-slide="${i}"></button>`).join('');
function renderSlide(){const s=slides[slide];$('#slide-title').innerHTML=s.title;$('#slide-desc').textContent=s.desc;$('.photo-caption').innerHTML=s.caption;$('#slide-count').textContent=`0${slide+1} / 04`;$$('[data-slide]').forEach((b,i)=>{b.classList.toggle('active',i===slide);b.setAttribute('aria-pressed',i===slide)});$('#pause').textContent=paused?'▷':'Ⅱ';$('#pause').setAttribute('aria-label',paused?'Slaytları oynat':'Slaytları duraklat')}
function schedule(){clearInterval(timer);if(!paused)timer=setInterval(()=>{if(!dialog.open&&!document.hidden){slide=(slide+1)%slides.length;renderSlide()}},7000)}
function changeSlide(n){slide=(n+slides.length)%slides.length;renderSlide();schedule()}
$('#prev').onclick=()=>changeSlide(slide-1);$('#next').onclick=()=>changeSlide(slide+1);$$('[data-slide]').forEach(b=>b.onclick=()=>changeSlide(Number(b.dataset.slide)));$('#pause').onclick=()=>{paused=!paused;renderSlide();schedule()};renderSlide();schedule();
function portrait(person){const url=imageURL(person.photo);return `<div class="portrait">${url?`<img src="${esc(url)}" alt="${esc(person.name||person.title)}">`:'<span class="silhouette" aria-hidden="true">♙</span><small>FOTOĞRAF ALANI</small>'}</div>`}
function selectCity(id,scroll=false){const b=data.branches.find(x=>x.id===id);if(!b)return;currentCity=id;$('#city-select').value=id;$('#map-label').textContent=b.city;$$('#turkiye > g').forEach(g=>{const selected=(g.id==='istanbul-asya'?'istanbul-avrupa':g.id)===id;g.classList.toggle('selected',selected);g.setAttribute('aria-pressed',selected)});$('#branch-info').innerHTML=`<div class="branch-code">${esc(b.code)}</div><h3>${esc(b.city)}</h3><p>İl Teşkilatı</p>${imageURL(b.photo)?`<img class="branch-photo" src="${esc(imageURL(b.photo))}" alt="${esc(b.name||b.city+' İl Başkanı')}">`:''}<div class="detail-line"><small>İL BAŞKANI</small>${esc(b.name||'Bilgi henüz eklenmedi')}</div><div class="detail-line"><small>ADRES</small>${esc(b.address||'Adres bilgisi henüz eklenmedi')}</div><div class="detail-line"><small>TELEFON</small>${b.phone?`<a href="tel:${esc(b.phone.replace(/[^+\d]/g,''))}">${esc(b.phone)}</a>`:'Telefon bilgisi henüz eklenmedi'}</div>${b.address?`<a class="text-button" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(b.address)}" target="_blank" rel="noopener">Yol tarifi al ↗</a>`:''}`;if(scroll)$('#subeler').scrollIntoView({behavior:'smooth'})}
function management(tab){currentTab=tab;$$('.tabs [data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',b.dataset.tab===tab)});const el=$('#management-content');if(tab==='president'){el.innerHTML=`<div class="president">${portrait(data.president)}<div class="president-copy"><p class="eyebrow">GENEL BAŞKAN</p><h3>${esc(data.president.name||'Genel Başkanımız')}</h3><p>${esc(data.president.bio||'Genel başkanın fotoğrafı, özgeçmişi ve mesajı bu alanda yer alacaktır.')}</p><button class="text-button" id="president-detail">Başkanın mesajı ↗</button></div></div>`;$('#president-detail').onclick=()=>openDialog(`<p class="eyebrow">GENEL BAŞKAN</p><h2>${esc(data.president.name||'Genel Başkanımız')}</h2><p>${esc(data.president.bio||'Başkanın özgeçmişi ve mesajı henüz eklenmedi.')}</p>`)}else if(tab==='board'){el.innerHTML=`<div class="board-grid">${data.board.map(p=>`<button class="person-card" data-person="${p.id}">${portrait(p)}<div class="person-text"><h3>${esc(p.name||p.title+' Başkanlığı')}</h3><p>${esc(p.name?p.title+' Başkanı':'İsim bilgisi eklenecek')}</p><span>↗</span></div></button>`).join('')}</div>`;$$('[data-person]').forEach(b=>b.onclick=()=>personDetail(Number(b.dataset.person)))}else{el.innerHTML='<input class="search" id="branch-search" aria-label="Şube başkanları arasında il ara" placeholder="İl adıyla arayın…"><div class="branch-list" id="branch-list"></div>';function list(q=''){$('#branch-list').innerHTML=data.branches.filter(b=>b.city.toLocaleLowerCase('tr').includes(q.toLocaleLowerCase('tr'))).map(b=>`<button data-branch="${b.id}">${esc(b.city)}<small>${esc(b.name||'Başkan bilgisi eklenecek')}</small></button>`).join('')||'<p>Aramanıza uygun il bulunamadı.</p>';$$('[data-branch]').forEach(b=>b.onclick=()=>selectCity(b.dataset.branch,true))}list();$('#branch-search').oninput=e=>list(e.target.value)}}
function personDetail(id){const p=data.board.find(p=>p.id===id);if(!p)return;openDialog(`<p class="eyebrow">BAŞKANLIK DİVANI</p><h2>${esc(p.name||p.title+' Başkanlığı')}</h2><p>${esc(p.title)} ${p.name?'Başkanı':''}</p><p>${esc(p.bio||'Özgeçmiş bilgisi henüz eklenmedi.')}</p><h3>Başkan Yardımcıları</h3>${p.assistants.length?p.assistants.map(a=>`<div class="assistant-card">${imageURL(a.photo)?`<img src="${esc(imageURL(a.photo))}" alt="${esc(a.name)}">`:''}<div><b>${esc(a.name)}</b><small>${esc(a.title||'Başkan Yardımcısı')}</small></div></div>`).join(''):'<p>Bu başkanlığa bağlı başkan yardımcıları henüz eklenmedi.</p>'}`)}
$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>management(b.dataset.tab)));
const pages={kurumsal:['KURUMSAL','Önce Ahlak ve Maneviyat.','Millî Gençlik Derneği; gençlerin ahlak, maneviyat, ilim ve sorumluluk bilinciyle gelişimini merkeze alır. Birlikte öğrenmeyi, üretmeyi ve toplum için faydalı olmayı önemser.','Çalışma anlayışımız','İnanç, ilim, plan ve program, kadro ve organizasyon, takip ve kontrol, intaç. Bu ilkeler çalışmalarımıza yön verir.'],yayinlar:['YAYINLAR','Gençliğin fikir dünyası.','Millî Gençlik yayınları; fikir, kültür, sanat ve gençlik çalışmalarını bir araya getirir.','Dijital yayınlar','Dergi ve yayın dosyaları bu bölüme eklenecektir.'],erbakan:['DÜŞÜNCE VE MİRAS','Prof. Dr. Necmettin Erbakan','İman, şuur ve emek merkezli gençlik anlayışı üzerine yazılar, okumalar ve kaynaklar.','Okuma alanı','Doğrulanmış yazılar ve kaynak bağlantıları bu bölüme eklenecektir.'],privacy:['GİZLİLİK','Verileriniz hakkında','Bu önizleme ziyaretçilerden form verisi veya ödeme bilgisi toplamaz. Dış bağlantılara geçildiğinde ilgili hizmetin gizlilik koşulları uygulanır.','İçerik taslakları','Taslak düzenleyicisinde kaydedilen içerikler yalnızca kullandığınız tarayıcıda tutulur. Tarayıcı verilerinin silinmesi taslakları kaldırır. Gerçek kişilerin bilgilerini yayımlamadan önce gerekli izinleri alın.']};
pages.videogaleri=['VİDEO GALERİSİ','Çalışmalarımızdan görüntüler.','Etkinliklerimizi, buluşmalarımızı ve gençlik çalışmalarımızı videolarla takip edin.','Video içerikleri','Galeri videoları eklendikçe bu alanda yer alacaktır.'];
pages.fotogaleri=['FOTO GALERİSİ','Etkinliklerden kareler.','Millî Gençlik Derneği çalışmalarından fotoğraf seçkileri.','Fotoğraf arşivi','Etkinlik fotoğrafları eklendikçe bu alanda yer alacaktır.'];
pages.etkinlikler=['ETKİNLİKLER','Gençliğin buluşma noktası.','Millî Gençlik Derneği etkinlikleri; eğitim, kültür, kardeşlik ve teşkilat buluşmalarını kapsar.','Programlar','Yaklaşan etkinlik programları ve kayıt bağlantıları bu alanda yayımlanacaktır.'];

const searchDialog=$('#search-dialog'),searchInput=$('#site-search'),searchResults=$('#search-results');let currentSearchResults=[];
const normalizeSearch=s=>String(s??'').toLocaleLowerCase('tr').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/\s+/g,' ').trim();
function buildSearchIndex(){const entries=[];const add=(title,body,target='',extra={})=>{const text=String(body??'').replace(/\s+/g,' ').trim();if(title||text)entries.push({title:String(title||'İçerik'),body:text,target,...extra})};document.querySelectorAll('header,.quick-link,main section,footer').forEach(node=>{const title=node.querySelector('h1,h2,h3')?.textContent?.trim()||node.getAttribute('aria-label')||node.textContent.trim().split(/\s+/).slice(0,5).join(' ');const body=node.innerText||node.textContent||'';const section=node.matches('section')?node:node.closest('section');const link=node.getAttribute('href');const target=section?.id?'#'+section.id:node.id?'#'+node.id:link?.startsWith('#')?link:'';add(title,body,target)});slides.forEach(s=>add(s.title.replace(/<[^>]*>/g,' '),s.desc,''));for(const [key,p] of Object.entries(pages))add(p[1],p.join(' '),'',{pageKey:key});if(data){if(data.president)add(data.president.name||'Genel Başkan',data.president.bio,'#yonetim',{tab:'president'});(data.board||[]).forEach(p=>{add(p.name||p.title+' Başkanlığı',[p.title,p.name,p.bio,...(p.assistants||[]).map(a=>a.name)].join(' '),'#yonetim',{tab:'board'})});(data.branches||[]).forEach(b=>add(b.city+' İl Teşkilatı',[b.name,b.address,b.phone].join(' '),'#subeler',{cityId:b.id}))}return entries}
function renderSearchResults(){const query=normalizeSearch(searchInput.value);if(!query){currentSearchResults=[];searchResults.innerHTML='<p class="search-hint">Aradığınız başlığı, kişiyi veya ili yazın.</p>';return}const terms=query.split(' ').filter(Boolean);currentSearchResults=buildSearchIndex().map(entry=>{const hay=normalizeSearch(entry.title+' '+entry.body);const matched=terms.filter(term=>hay.includes(term)).length;return{...entry,score:matched+(normalizeSearch(entry.title).includes(query)?3:0)}}).filter(entry=>entry.score>=terms.length).sort((a,b)=>b.score-a.score).slice(0,8);if(!currentSearchResults.length){searchResults.innerHTML='<p class="search-empty">Bu aramayla eşleşen bir içerik bulunamadı.</p>';return}searchResults.innerHTML=currentSearchResults.map((entry,i)=>'<button class="search-result" type="button" data-search-result="'+i+'"><span><b>'+esc(entry.title)+'</b><small>'+esc(entry.body.slice(0,150)||'İçeriği görüntüle')+'</small></span><i aria-hidden="true">↗</i></button>').join('');searchResults.querySelectorAll('[data-search-result]').forEach(button=>button.onclick=()=>{const entry=currentSearchResults[Number(button.dataset.searchResult)];searchDialog.close();if(entry.pageKey){const p=pages[entry.pageKey];openDialog('<p class="eyebrow">'+esc(p[0])+'</p><h2>'+esc(p[1])+'</h2><p>'+esc(p[2])+'</p><h3>'+esc(p[3])+'</h3><p>'+esc(p[4])+'</p>');return}if(entry.tab)management(entry.tab);if(entry.cityId)selectCity(entry.cityId,true);else if(entry.target&&$(entry.target))$(entry.target).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})})}
$('#search-toggle').onclick=()=>{searchDialog.showModal();renderSearchResults();searchInput.focus()};$('#search-close').onclick=()=>searchDialog.close();searchInput.oninput=renderSearchResults;searchDialog.addEventListener('click',e=>{if(e.target===searchDialog)searchDialog.close()});

$$('[data-page]').forEach(b=>b.onclick=()=>{const p=pages[b.dataset.page];openDialog(`<p class="eyebrow">${p[0]}</p><h2>${p[1]}</h2><p>${p[2]}</p><h3>${p[3]}</h3><p>${p[4]}</p>`)});
