dialog.addEventListener('click',e=>{if(e.target.closest('#activity-branch,#volunteer-branch')){dialog.close();$('#subeler').scrollIntoView({behavior:'smooth'})}});
$$('[data-volunteer]').forEach(b=>b.onclick=()=>openDialog('<p class="eyebrow">GÖNÜLLÜLÜK</p><h2>Bu yolculukta yeriniz var.</h2><p>Gönüllülük ve yerel çalışmalar için size en yakın il teşkilatını seçerek iletişim bilgilerine ulaşabilirsiniz.</p><button class="button primary" id="volunteer-branch">İl teşkilatını bul ↗</button>'));
$$('[data-donate]').forEach(b=>b.onclick=()=>{const d=data.donation;openDialog(`<p class="eyebrow">DAYANIŞMA</p><h2>İyiliğe destek olun.</h2><p>Millî Gençlik Derneği gençlik çalışmalarına destek.</p>${d.iban&&d.recipient?`<div class="detail-line"><small>HESAP SAHİBİ</small>${esc(d.recipient)}</div><div class="detail-line"><small>IBAN</small><b>${esc(d.iban)}</b></div><button id="copy-iban" class="button primary">IBAN'ı kopyala</button><p id="copy-status" role="status"></p>`:'<div class="notice">Bağış hesabı henüz tanımlanmadı. Bu önizleme üzerinden ödeme alınmıyor.</div>'}${safeURL(d.paymentUrl)?`<p><a class="button primary" href="${esc(safeURL(d.paymentUrl))}" target="_blank" rel="noopener">Güvenli bağış sayfasına git ↗</a></p>`:''}`);if($('#copy-iban'))$('#copy-iban').onclick=async()=>{try{await navigator.clipboard.writeText(d.iban);$('#copy-status').textContent='IBAN kopyalandı.'}catch{$('#copy-status').textContent='Kopyalanamadı. IBAN’ı seçerek kopyalayabilirsiniz.'}}});
function renderContact(){const c=data.contact;$('#contact-details').innerHTML=`${c.phone?`<p><a href="tel:${esc(c.phone.replace(/[^+\d]/g,''))}">${esc(c.phone)}</a></p>`:''}${c.email?`<p><a href="mailto:${esc(c.email)}">${esc(c.email)}</a></p>`:''}${c.address?`<p>${esc(c.address)}</p>`:''}`}
function renderPioneers(){const list=$('#pioneer-list');if(!list||!data?.pioneers)return;list.innerHTML=data.pioneers.map((p,i)=>{const image=imageURL(p.photo);return `<article class="pioneer-card ${i===0?'is-open':''}" data-pioneer-card data-index="${i}"><div class="pioneer-art ${image?'has-image':''}">${image?`<img src="${image}" alt="" loading="lazy">`:''}<span class="pioneer-art-mark" aria-hidden="true">MG</span></div><button class="pioneer-trigger" type="button" aria-expanded="${i===0?'true':'false'}"><span class="pioneer-name">${esc(p.name||'Öncü Şahsiyet')}</span><span class="pioneer-years">${esc(p.years||'')}</span><span class="pioneer-number">0${i+1}</span></button><div class="pioneer-detail"><p>${esc(p.summary||'')}</p><button class="pioneer-more" type="button" data-pioneer-open="${i}">Tanımak için tıkla <span aria-hidden="true">↗</span></button></div></article>`}).join('');$$('[data-pioneer-card]').forEach(card=>{card.querySelector('.pioneer-trigger').onclick=()=>setPioneerOpen(Number(card.dataset.index));card.querySelector('[data-pioneer-open]').onclick=()=>{const p=data.pioneers[Number(card.dataset.index)];openDialog(`<p class="eyebrow">ÖNCÜ ŞAHSİYETLER · ${esc(p.years||'')}</p><h2>${esc(p.name)}</h2><p>${esc(p.detail||p.summary)}</p>`)}});if(!window.pioneerScrollBound){window.pioneerScrollBound=true;let raf=0;window.addEventListener('scroll',()=>{if(raf)return;raf=requestAnimationFrame(()=>{raf=0;const section=$('#pioneers');if(!section)return;const rect=section.getBoundingClientRect();if(rect.bottom<80||rect.top>innerHeight*.82)return;const cards=$$('[data-pioneer-card]');const aim=innerHeight*.48;let best=null,dist=Infinity;cards.forEach(card=>{const r=card.getBoundingClientRect(),d=Math.abs((r.top+r.height*.5)-aim);if(d<dist){dist=d;best=card}});if(best&&dist<innerHeight*.34)setPioneerOpen(Number(best.dataset.index))})},{passive:true})}initScrollReveals()}
function setPioneerOpen(index){$$('[data-pioneer-card]').forEach((card,i)=>{const open=i===index;card.classList.toggle('is-open',open);card.querySelector('.pioneer-trigger')?.setAttribute('aria-expanded',String(open))})}

const siteEvents=[{date:'2026-12-31',title:'Mekke’nin Fethi Programı',description:'Mekke’nin Fethi’nin yıl dönümünde düzenlenecek programımız.'}];
let calendarCursor=new Date(2026,11,1);
function renderCalendar(){const month=$('#calendar-month'),days=$('#calendar-days'),upcoming=$('#upcoming-events');if(!month||!days||!upcoming)return;const year=calendarCursor.getFullYear(),m=calendarCursor.getMonth();month.textContent=new Intl.DateTimeFormat('tr-TR',{month:'long',year:'numeric'}).format(calendarCursor);const offset=(new Date(year,m,1).getDay()+6)%7,total=new Date(year,m+1,0).getDate(),events=siteEvents.filter(e=>{const d=new Date(e.date+'T12:00:00');return d.getFullYear()===year&&d.getMonth()===m});let html=Array(offset).fill('<span class="calendar-empty" aria-hidden="true"></span>').join('');for(let day=1;day<=total;day++){const iso=year+'-'+String(m+1).padStart(2,'0')+'-'+String(day).padStart(2,'0'),event=siteEvents.find(e=>e.date===iso);html+=event?'<button class="calendar-day has-event" type="button" data-event-date="'+iso+'" aria-label="'+day+' '+esc(event.title)+'">'+day+'<i aria-hidden="true"></i></button>':'<span class="calendar-day">'+day+'</span>'}days.innerHTML=html;upcoming.innerHTML=events.length?'<p class="upcoming-heading">YAKLAŞAN ETKİNLİK</p>'+events.map(e=>'<button class="upcoming-event" type="button" data-event-date="'+e.date+'"><i class="pulse-dot" aria-hidden="true"></i><span><b>'+esc(e.title)+'</b><small>'+new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric'}).format(new Date(e.date+'T12:00:00'))+'</small></span><em>↗</em></button>').join(''):'<p class="upcoming-empty">Bu ay için duyurulmuş etkinlik bulunmuyor.</p>';document.querySelectorAll('[data-event-date]').forEach(button=>button.onclick=()=>{const event=siteEvents.find(e=>e.date===button.dataset.eventDate);if(event)openDialog('<p class="eyebrow">31 ARALIK 2026 · DUYURU</p><h2>'+esc(event.title)+'</h2><p>'+esc(event.description)+'</p>')})}
$('#calendar-prev').onclick=()=>{calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()-1,1);renderCalendar()};
$('#calendar-next').onclick=()=>{calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+1,1);renderCalendar()};
function initScrollReveals(){
 const targets=document.querySelectorAll('main > section:not(.hero-banner), .quick-links, [data-pioneer-card], [data-reveal]');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 if(!('IntersectionObserver' in window)||reduced.matches){targets.forEach(el=>{el.classList.remove('scroll-reveal');el.classList.add('is-visible')});return}
 if(!window.siteRevealObserver){
  window.siteRevealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{
   // Keep content above the viewport visible; rewind only when returning below it.
   const visible=entry.isIntersecting||entry.boundingClientRect.top<0;
   entry.target.classList.toggle('is-visible',visible);
  }),{threshold:0,rootMargin:'0px 0px -6% 0px'});
  reduced.addEventListener('change',()=>{window.siteRevealObserver.disconnect();window.siteRevealObserver=null;document.querySelectorAll('.scroll-reveal').forEach(el=>el.classList.remove('scroll-reveal'));initScrollReveals()});
 }
 targets.forEach(el=>{if(el.classList.contains('scroll-reveal'))return;el.classList.remove('reveal-ready');el.classList.add('scroll-reveal');el.classList.toggle('is-visible',el.getBoundingClientRect().top<innerHeight*.94);window.siteRevealObserver.observe(el)});
}

