async function init(){try{const [dr,mr]=await Promise.all([fetch('data.json'),fetch('assets/turkey.svg')]);if(!dr.ok||!mr.ok)throw new Error('assets');baseData=await dr.json();data=structuredClone(baseData);try{const cached=JSON.parse(localStorage.getItem('mgd-draft-v1'));if(cached&&Array.isArray(cached.branches)&&cached.branches.length===81&&Array.isArray(cached.board)&&cached.president&&cached.contact&&cached.donation)data=cached}catch{}if(!Array.isArray(data.pioneers)||!data.pioneers.length)data.pioneers=structuredClone(baseData.pioneers||[]);$('#map').innerHTML=await mr.text();const known=new Set(data.branches.map(b=>b.id));$$('#turkiye > g').forEach(g=>{const cityId=g.id==='istanbul-asya'?'istanbul-avrupa':g.id;if(!known.has(cityId))return;g.setAttribute('tabindex','0');g.setAttribute('role','button');g.setAttribute('aria-label',g.dataset.iladi+' il teşkilatı');g.onclick=()=>selectCity(cityId);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectCity(cityId)}};g.onmouseenter=()=>$('#map-label').textContent=g.dataset.iladi;g.onmouseleave=()=>$('#map-label').textContent=data.branches.find(b=>b.id===currentCity).city});data.branches.sort((a,b)=>a.city.localeCompare(b.city,'tr'));$('#city-select').innerHTML=data.branches.map(b=>`<option value="${b.id}">${esc(b.city)}</option>`).join('');$('#city-select').onchange=e=>selectCity(e.target.value);selectCity(currentCity);management(currentTab);renderContact();renderPioneers()}catch(e){$('#map').innerHTML='<p>Harita yüklenemedi. Lütfen sayfayı yenileyin.</p>';$('#management-content').innerHTML='<p>İçerikler yüklenemedi. Lütfen sayfayı yenileyin.</p>'}}
